import chess

def mate_in(board, depth):
    # returns positive N if side to move can force mate in N plies (mate delivered), 
    # large value meaning faster mate. We return best (max) mate score for side to move.
    # Score convention: MATE - plies_to_mate for winning; None if no forced mate within depth.
    if board.is_checkmate():
        return -10000  # side to move is mated (bad for side to move)
    if depth == 0:
        return None
    best = None
    for mv in board.legal_moves:
        board.push(mv)
        val = mate_in(board, depth-1)
        board.pop()
        if val is None:
            child = None
        else:
            child = -val  # negamax
        if child is not None:
            if best is None or child > best:
                best = child
    return best

board = chess.Board('r1bq1r2/1p3pp1/p1n1p3/3nPkbP/8/P1N5/1P2QPP1/R1B1K2R w KQ - 0 16')
# search increasing depth
for d in range(1,7):
    results = []
    for mv in board.legal_moves:
        board.push(mv)
        val = mate_in(board, d-1)
        board.pop()
        if val is not None:
            score = -val
            results.append((score, mv))
    # find winning mates: score close to 10000
    mates = [(s,m) for s,m in results if s > 5000]
    if mates:
        best_score = max(s for s,m in mates)
        winning = sorted([m for s,m in mates if s==best_score], key=lambda x:x.uci())
        print('Depth', d, 'plies -> mate found. Best score', best_score)
        print('Moves forcing fastest mate:', [m.uci() for m in winning])
        break
    else:
        print('Depth', d, ': no forced mate yet')
